-- QA ONLY. The checked-in additive migrations assume an older hosted schema.
-- Empty compatibility tables supply those dependencies; no production rows are imported.
-- This is not claimed to reconstruct the full historical schema.
begin;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, avatar_url text);
alter table public.profiles enable row level security;
create policy qa_profile_owner on public.profiles to authenticated using (id = (select auth.uid())) with check (id = (select auth.uid()));
create table public.reading_groups (code text primary key, name text, description text, goal text, unit text, owner_id uuid references auth.users(id), created_at timestamptz default now());
create table public.reading_group_members (id bigint generated by default as identity primary key, group_code text, user_id uuid, display_name text, role text, created_at timestamptz default now());
create table public.reading_group_feed (id bigint generated by default as identity primary key, group_code text, user_id uuid, display_name text, type text, message text, unit text, amount integer, created_at timestamptz default now());
create table public.reading_group_feed_comments (id bigint generated by default as identity primary key, group_code text, post_id bigint, user_id uuid, display_name text, content text, created_at timestamptz default now(), updated_at timestamptz default now());
create table public.reading_group_feed_likes (id bigint generated by default as identity primary key, group_code text, post_id bigint, user_id uuid, created_at timestamptz default now());
create table public.reading_group_progress (id bigint generated by default as identity primary key, group_code text, user_id uuid, unit text, amount integer, source text, date_key text, created_at timestamptz default now());
alter table public.reading_groups enable row level security;
alter table public.reading_group_members enable row level security;
alter table public.reading_group_feed enable row level security;
alter table public.reading_group_feed_comments enable row level security;
alter table public.reading_group_feed_likes enable row level security;
alter table public.reading_group_progress enable row level security;
commit;
